requested_tables(schema_name,name) as (values ('private','edu_campus_community_flow_receipts'),('private','edu_campus_community_receipts'),('private','edu_campus_office_connectors'),('private','edu_campus_office_events'),('private','edu_campus_office_receipts'),('public','cohorts'),('public','courses'),('public','curriculum_lessons'),('public','curriculum_missions'),('public','curriculum_weeks'),('public','edu_ai_calls'),('public','edu_ai_cohort_settings'),('public','edu_ai_conversation_turns'),('public','edu_ai_conversations'),('public','edu_ai_requests'),('public','edu_campus_archive_commands'),('public','edu_campus_archive_entries'),('public','edu_campus_blocks'),('public','edu_campus_business_case_events'),('public','edu_campus_business_cases'),('public','edu_campus_business_records'),('public','edu_campus_business_review_links'),('public','edu_campus_business_review_replies'),('public','edu_campus_comments'),('public','edu_campus_community_flow_history'),('public','edu_campus_demo_questions'),('public','edu_campus_demo_slots'),('public','edu_campus_exchanges'),('public','edu_campus_feedback_acknowledgments'),('public','edu_campus_focus_sessions'),('public','edu_campus_launches'),('public','edu_campus_moderation_log'),('public','edu_campus_office_bookings'),('public','edu_campus_office_history'),('public','edu_campus_office_jobs'),('public','edu_campus_office_sessions'),('public','edu_campus_portfolio_file_access_log'),('public','edu_campus_portfolio_files'),('public','edu_campus_post_revisions'),('public','edu_campus_posts'),('public','edu_campus_preferences'),('public','edu_campus_reports'),('public','edu_campus_reward_rules'),('public','edu_campus_space_chat'),('public','edu_campus_space_controls'),('public','edu_campus_space_presence'),('public','edu_campus_space_profiles'),('public','edu_campus_space_seats'),('public','edu_campus_support_actions'),('public','edu_campus_support_requests'),('public','edu_cohort_lesson_visibility'),('public','edu_cohort_progression_settings'),('public','edu_cohort_week_visibility'),('public','edu_enrollment_progression_grants'),('public','edu_learning_notice_control'),('public','edu_lesson_answer_files'),('public','edu_lesson_block_drafts'),('public','edu_lesson_block_feedback'),('public','edu_lesson_block_heads'),('public','edu_lesson_block_reviews'),('public','edu_lesson_block_submissions'),('public','edu_lesson_block_versions'),('public','edu_lesson_media'),('public','edu_member_messages'),('public','edu_message_batches'),('public','edu_push_control'),('public','edu_push_deliveries'),('public','edu_push_events'),('public','edu_push_subscriptions'),('public','edu_question_answer_images'),('public','edu_question_answers'),('public','edu_question_assist_jobs'),('public','edu_question_images'),('public','edu_questions'),('public','edu_shared_answers'),('public','enrollments'),('public','lesson_contents'),('public','lesson_progress'),('public','mission_submissions'),('public','profiles')),
function_rows as (
 select r.name,n.nspname as schema_name,p.oid is not null as present,
 pg_get_function_identity_arguments(p.oid) as identity_arguments,
 pg_get_function_result(p.oid) as returns,p.prosecdef as security_definer,
 case when p.oid is not null then has_function_privilege('anon',p.oid,'EXECUTE') end as anon_execute,
 case when p.oid is not null then has_function_privilege('authenticated',p.oid,'EXECUTE') end as authenticated_execute,
 case when p.oid is not null then has_function_privilege('service_role',p.oid,'EXECUTE') end as service_execute
 from requested_functions r left join pg_proc p on p.proname=r.name and p.pronamespace in (select oid from pg_namespace where nspname in ('public','private','edu_private'))
 left join pg_namespace n on n.oid=p.pronamespace
),table_rows as (
 select r.schema_name,r.name,c.oid is not null as present,c.relrowsecurity as rls_enabled,
 coalesce((select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull) order by a.attnum) from pg_attribute a where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),'[]'::jsonb) as columns
 from requested_tables r left join pg_namespace n on n.nspname=r.schema_name left join pg_class c on c.relnamespace=n.oid and c.relname=r.name and c.relkind in ('r','p','v','m')
)
select jsonb_build_object('functions',(select jsonb_agg(to_jsonb(f) order by f.name,f.schema_name,f.identity_arguments) from function_rows f),'tables',(select jsonb_agg(to_jsonb(t) order by t.schema_name,t.name) from table_rows t),'migrationHistoryRelation',to_regclass('supabase_migrations.schema_migrations')::text) as metadata;
